procedure.header:
#include "autopilot.h"
#include "firmwares/fixedwing/guidance/energy_ctrl.h"
#include "modules/digital_cam/dc.h"
#include "modules/nav/nav_survey_poly_osam.h"
#include "modules/nav/nav_mission4_geofence.h"

/* Offset of the MS plan's origin in this plan's frame (UTM, metres).
   Position in the MS frame = position here - offset. */
#define MISSION1_MS_FRAME_DX (-24.923f)
#define MISSION1_MS_FRAME_DY (233.862f)

/* Buffered Strasbourg flyzone check (polygon in nav_mission4_geofence.h is
   in the MS frame). */
static inline bool mission1_in_flyzone(float x, float y, float buf)
{
  return mission4_near_poly(mission4_strasbourg_vx, mission4_strasbourg_vy, 6,
                            x - MISSION1_MS_FRAME_DX, y - MISSION1_MS_FRAME_DY, buf);
}

/* Photo-number block per mapping area: shots in area k are k*1000 + 1, +2 ...
   dc_photo_nr is the number of the LAST shot and is incremented before
   sending, so setting it to k*1000 makes the first frame k*1000 + 1. */
#define MISSION1_PHOTO_BLOCK 1000

/* tan(half of the camera FOV ACROSS the flight line). The AI Camera is
   66 x 52.3 deg, mounted with the 66 deg axis ACROSS THE WINGS:
   2 * 60 m * tan(33) = 77.9 m swath. If it turns out to be the other way
   round, use 0.49098f (tan 26.15 deg, 58.9 m swath at 60 m). */
#define MISSION1_TAN_HALF_CROSS_FOV 0.64941f

/* Survey line angle parallel to the edge wp_a-wp_b, in the module's own
   convention (atan(dy/dx), degrees), so the lines follow the corners when
   they are dragged in the GCS. dx is nudged off zero like the module does. */
static inline float mission1_line_angle(uint8_t wp_a, uint8_t wp_b)
{
  float dx = waypoints[wp_b].x - waypoints[wp_a].x;
  float dy = waypoints[wp_b].y - waypoints[wp_a].y;
  if (signbit(fabs(dx) - 0.000001f)) { dx = 0.000001f; }
  return DegOfRad(atan(dy / dx));
}

/* Point on the edge a-b, pushed `m` metres away from (cx, cy), where the
   across-line coordinate x*nx + y*ny equals T. */
static inline void mission1_edge_at(uint8_t a, uint8_t b, float cx, float cy, float m,
    float nx, float ny, float T, float *px, float *py)
{
  float ax = waypoints[a].x, ay = waypoints[a].y;
  float bx = waypoints[b].x, by = waypoints[b].y;
  float dx = bx - ax, dy = by - ay;
  float len = sqrtf(dx * dx + dy * dy);
  if (signbit(len - 0.001f)) { len = 1.0f; }
  float ex = -dy / len, ey = dx / len;
  if (!signbit((cx - ax) * ex + (cy - ay) * ey)) { ex = -ex; ey = -ey; }
  ax += ex * m; ay += ey * m;
  bx += ex * m; by += ey * m;
  float ta = ax * nx + ay * ny;
  float den = bx * nx + by * ny - ta;
  if (signbit(fabs(den) - 0.001f)) { den = 0.001f; }
  float u = (T - ta) / den;
  *px = ax + u * (bx - ax);
  *py = ay + u * (by - ay);
}

/* Turn radius the module will use: half the sweep, but never below its
   POLY_OSAM_MIN_RADIUS (module default 30 unless the airframe sets it). */
#ifdef POLY_OSAM_MIN_RADIUS
#define MISSION1_MIN_TURN_RADIUS ((float)POLY_OSAM_MIN_RADIUS)
#else
#define MISSION1_MIN_TURN_RADIUS 30.0f
#endif
/* Never pull an edge in by more than this along the lines. */
#define MISSION1_MAX_INSET 80.0f
/* Entry circle radius (Poly_Entry_Radius): the module then puts the entry
   circle tangent to the first line instead of round the polygon corner
   with half the sweep (~52 m), which stuck far out at the Area 2 SE corner
   and forced the south edge ~38 m in. */
#define MISSION1_ENTRY_RADIUS 30.0f

/* How far (along the lines, metres) a circle centre at (x, y) must move
   by -d * (ux, uy) so a circle of radius r stays `margin` inside the convex
   border polygon gx/gy (4 corners, either winding). Border sides that the
   move barely changes the distance to are ignored (it cannot help there). */
static inline float mission1_inset_needed(float x, float y, float ux, float uy,
    float r, float margin, float *gx, float *gy)
{
  float mx = 0.25f * (gx[0] + gx[1] + gx[2] + gx[3]);
  float my = 0.25f * (gy[0] + gy[1] + gy[2] + gy[3]);
  float need = 0.0f;
  uint8_t i;
  for (i = 0; i != 4; i++) {
    uint8_t j = (i + 1) % 4;
    float ex = gx[j] - gx[i], ey = gy[j] - gy[i];
    float len = sqrtf(ex * ex + ey * ey);
    if (signbit(len - 0.001f)) { continue; }
    float gnx = -ey / len, gny = ex / len;   /* made to point inward below */
    if (signbit((mx - gx[i]) * gnx + (my - gy[i]) * gny)) { gnx = -gnx; gny = -gny; }
    float dist = (x - gx[i]) * gnx + (y - gy[i]) * gny;
    float lack = r + margin - dist;
    float gain = -(ux * gnx + uy * gny);
    if (signbit(lack) || signbit(gain - 0.1f)) { continue; }
    float d = lack / gain;
    if (signbit(need - d)) { need = d; }
  }
  if (signbit(MISSION1_MAX_INSET - need)) { need = MISSION1_MAX_INSET; }
  return need;
}

/* Perpendicular distance to pull the edge a-b (currently pushed `overrun`
   out) in, so every U-turn circle of this pass on that edge, and the entry
   circle at that edge's corner on the entry side, stay `margin` inside the
   border. With Poly_Turn_On_Edge a U-turn centre (radius r) sits on the
   scratch edge midway between the two lines; the entry circle (radius
   r_entry, module: first line's start level) sits r_entry from the first
   line T_first towards the entry side T_side. 0 when nothing needs to
   move. */
static inline float mission1_edge_pull(uint8_t a, uint8_t b, float cx, float cy,
    float overrun, float nx, float ny, float lo, float s, int kmin, int kmax,
    int kstep, float T_side, float T_first, float r, float r_entry, float margin,
    float *gx, float *gy)
{
  float ux = ny, uy = -nx;   /* along the lines */
  float p[2];   /* p + 0 / p + 1, not the address-of form (XML) */
  mission1_edge_at(a, b, cx, cy, overrun, nx, ny, T_first, p + 0, p + 1);
  if (signbit((p[0] - cx) * ux + (p[1] - cy) * uy)) { ux = -ux; uy = -uy; }   /* out of the area */

  float d = 0.0f, di;
  int k;
  for (k = kmin; !signbit((float)(kmax - k - kstep)); k += kstep) {
    float T = lo + ((float)k + 0.5f + 0.5f * (float)kstep) * s;
    mission1_edge_at(a, b, cx, cy, overrun, nx, ny, T, p + 0, p + 1);
    di = mission1_inset_needed(p[0], p[1], ux, uy, r, margin, gx, gy);
    if (signbit(d - di)) { d = di; }
  }
  mission1_edge_at(a, b, cx, cy, overrun, nx, ny, T_first, p + 0, p + 1);
  float toward = signbit(T_side - T_first) ? -r_entry : r_entry;
  p[0] += toward * nx;
  p[1] += toward * ny;
  di = mission1_inset_needed(p[0], p[1], ux, uy, r_entry, margin, gx, gy);
  if (signbit(d - di)) { d = di; }

  /* along-line distance d = perpendicular edge shift / |cos| */
  float ex = waypoints[b].x - waypoints[a].x, ey = waypoints[b].y - waypoints[a].y;
  float len = sqrtf(ex * ex + ey * ey);
  if (signbit(len - 0.001f)) { return 0.0f; }
  return d * fabsf((ux * ey - uy * ex) / len);
}

/* Set up ONE PASS of a survey of the quadrilateral n0-n1 (north edge),
   s0-s1 (south edge), lines parallel to edge_a-edge_b. N lines at
   (k + 0.5) * W / N across the width W.
   passes == 1: the single pass flies all N lines in order, at spacing s.
     It starts on ref_wp's side, or ENDS there if end_on_ref.
   passes == 2: interleaved; pass 1 flies the lines of the same parity as
     the outer line on ref_wp's side, pass 2 the others, at spacing 2 * s.
   Each pass is a nav_survey_poly_osam run over the scratch polygon
   out_wp .. out_wp+3 (consecutive), whose north/south edges are the area's
   edges pushed `overrun` metres outward, then each pulled back in as far
   as needed to keep this pass's U-turn and entry circles `margin` metres
   inside the border geofence g0..g3. Returns the number of lines in the
   pass; 0 means none (survey not set up). */
static inline uint8_t mission1_pass_setup(uint8_t n0, uint8_t n1, uint8_t s0, uint8_t s1,
    uint8_t edge_a, uint8_t edge_b, uint8_t ref_wp, bool end_on_ref,
    uint8_t passes, uint8_t pass,
    float max_sweep, float overrun, float alt, uint8_t out_wp,
    uint8_t g0, uint8_t g1, uint8_t g2, uint8_t g3, float margin)
{
  float angle = mission1_line_angle(edge_a, edge_b);
  float th = RadOfDeg(angle);
  float nx = -sinf(th), ny = cosf(th);
  uint8_t c[4] = {n0, n1, s0, s1};
  float lo = 0.0f, hi = 0.0f, cx = 0.0f, cy = 0.0f;
  uint8_t i;
  for (i = 0; i != 4; i++) {
    float t = waypoints[c[i]].x * nx + waypoints[c[i]].y * ny;
    if (i == 0) { lo = t; hi = t; }
    if (signbit(t - lo)) { lo = t; }
    if (!signbit(t - hi)) { hi = t; }
    cx += 0.25f * waypoints[c[i]].x;
    cy += 0.25f * waypoints[c[i]].y;
  }
  float width = hi - lo;
  if (signbit(max_sweep - 1.0f)) { max_sweep = 1.0f; }
  /* -0.001: a width of exactly k strips must give k lines, not k+1 */
  float nl = ceilf(width / max_sweep - 0.001f);
  if (signbit(nl - 1.0f)) { nl = 1.0f; }
  int N = (int)nl;
  float s = width / nl;

  float tref = waypoints[ref_wp].x * nx + waypoints[ref_wp].y * ny;
  bool ref_low = signbit(tref - 0.5f * (lo + hi));
  int k_ref = ref_low ? 0 : N - 1;
  int kmin = 0;
  int kmax = N - 1;
  int kstep = 1;
  if (passes == 2) {
    int parity = (pass == 1) ? (k_ref % 2) : ((k_ref + 1) % 2);
    kmin = parity;
    kmax = (((N - 1) % 2) == parity) ? N - 1 : N - 2;
    kstep = 2;
  }
  if (signbit((float)(kmax - kmin))) { return 0; }

  /* nav_survey_poly_osam puts the first line half a sweep inside the
     polygon and sweeps back when the next line would be past the far edge,
     so the polygon extends half a sweep beyond the outer lines. */
  float sweep = (float)kstep * s;
  float plo = lo + ((float)kmin + 0.5f) * s - 0.5f * sweep;
  float phi = lo + ((float)kmax + 0.5f) * s + 0.5f * sweep;

  float px = stateGetPositionEnu_f()[0].x;
  float py = stateGetPositionEnu_f()[0].y;
  bool entry_low = ref_low;
  if (passes != 2) {
    if (end_on_ref) { entry_low = !ref_low; }
  }
  if (pass != 1) { entry_low = signbit(px * nx + py * ny - 0.5f * (plo + phi)); }

  /* Keep the circles inside the border geofence: pull each edge in. */
  float r = 0.5f * sweep;
  if (signbit(r - MISSION1_MIN_TURN_RADIUS)) { r = MISSION1_MIN_TURN_RADIUS; }
  uint8_t g[4] = {g0, g1, g2, g3};
  float gx[4], gy[4];
  for (i = 0; i != 4; i++) {
    gx[i] = waypoints[g[i]].x;
    gy[i] = waypoints[g[i]].y;
  }
  float T_side = entry_low ? plo : phi;
  float T_first = entry_low ? plo + 0.5f * sweep : phi - 0.5f * sweep;
  float m_n = overrun - mission1_edge_pull(n0, n1, cx, cy, overrun, nx, ny, lo, s,
      kmin, kmax, kstep, T_side, T_first, r, MISSION1_ENTRY_RADIUS, margin, gx, gy);
  float m_s = overrun - mission1_edge_pull(s0, s1, cx, cy, overrun, nx, ny, lo, s,
      kmin, kmax, kstep, T_side, T_first, r, MISSION1_ENTRY_RADIUS, margin, gx, gy);
  Poly_Entry_Radius = MISSION1_ENTRY_RADIUS;

  float x[4], y[4];
  /* x + k, not the address-of form: a raw ampersand is not valid XML */
  mission1_edge_at(n0, n1, cx, cy, m_n, nx, ny, plo, x + 0, y + 0);
  mission1_edge_at(n0, n1, cx, cy, m_n, nx, ny, phi, x + 1, y + 1);
  mission1_edge_at(s0, s1, cx, cy, m_s, nx, ny, phi, x + 2, y + 2);
  mission1_edge_at(s0, s1, cx, cy, m_s, nx, ny, plo, x + 3, y + 3);
  uint8_t cn = entry_low ? 0 : 1;   /* north corner on the entry side */
  uint8_t cs = entry_low ? 3 : 2;   /* south corner on the entry side */
  float dn = (x[cn] - px) * (x[cn] - px) + (y[cn] - py) * (y[cn] - py);
  float ds = (x[cs] - px) * (x[cs] - px) + (y[cs] - py) * (y[cs] - py);
  uint8_t first = signbit(dn - ds) ? cn : cs;

  /* rotate the cyclic order so the entry corner comes first */
  for (i = 0; i != 4; i++) {
    uint8_t j = (first + i) % 4;
    waypoints[out_wp + i].x = x[j];
    waypoints[out_wp + i].y = y[j];
    waypoints[out_wp + i].a = alt;
  }
  nav_survey_poly_osam_setup(out_wp, 4, sweep, angle);
  return (uint8_t)((kmax - kmin) / kstep + 1);
}

/* Shoot only within alt_tol of the survey altitude, only while the GROUND
   TRACK runs along the survey lines (within max_course_err_deg), and only
   inside the area being mapped (now AND `lookahead` seconds ahead). Area
   corners are passed as waypoint ids because this header is emitted before
   the WP_ defines; n is up to 6, unused ids are ignored.
   Sets dc_autoshoot directly rather than dc_stop()/dc_distance(): those send
   DC_INFO on every call and dc_distance() resets the last shot position.
   No raw angle brackets or ampersands anywhere in this header: they make
   the flight plan invalid XML. */
static inline void mission1_shoot_in_area(float max_roll_deg, float lookahead,
    float alt_now, float alt_target, float alt_tol,
    float line_angle_deg, float max_course_err_deg, uint8_t n,
    uint8_t w0, uint8_t w1, uint8_t w2, uint8_t w3, uint8_t w4, uint8_t w5)
{
  uint8_t ids[6] = {w0, w1, w2, w3, w4, w5};
  float vx[6], vy[6];
  uint8_t i;
  for (i = 0; i != n; i++) {
    vx[i] = waypoints[ids[i]].x;
    vy[i] = waypoints[ids[i]].y;
  }
  /* Roll no longer gates shots: shoot at any bank angle. */
  (void)max_roll_deg;
  bool shoot = true;
  float x = stateGetPositionEnu_f()[0].x;
  float y = stateGetPositionEnu_f()[0].y;
  float ax = x + stateGetSpeedEnu_f()[0].x * lookahead;
  float ay = y + stateGetSpeedEnu_f()[0].y * lookahead;
  if (!mission4_in_poly(vx, vy, n, x, y)) { shoot = false; }
  if (!mission4_in_poly(vx, vy, n, ax, ay)) { shoot = false; }
  if (!signbit(fabs(alt_now - alt_target) - alt_tol)) { shoot = false; }
  float sx = stateGetSpeedEnu_f()[0].x;
  float sy = stateGetSpeedEnu_f()[0].y;
  float track_err = fmod(fabs(DegOfRad(atan2f(sy, sx)) - line_angle_deg), 180.0f);
  if (!signbit(track_err - 90.0f)) { track_err = 180.0f - track_err; }
  if (!signbit(track_err - max_course_err_deg)) { shoot = false; }
  if (shoot) {
    dc_autoshoot = DC_AUTOSHOOT_DISTANCE;
  } else {
    dc_autoshoot = DC_AUTOSHOOT_STOP;
  }
}
